static int32_t OEMWriteTokenB(const char* token, uint32_t len)
{
    char tokenWithFlagB[TOKEN_WITH_FLAG_SIZE] = {0};
    uint8_t flag[TOKEN_FLAG_SIZE] = {0};
    SetTokenFlag(flag, 2);
    if ((memcpy_s(tokenWithFlagB, TOKEN_WITH_FLAG_SIZE, token, len) != 0) ||
