// hal_sys_param.c（节选）
#include <pthread.h>
#include <sys/stat.h>
#include <stdlib.h>

const char* HalGetSerial(void)
{
    static char str[STR_MAX] = {0};
    char strOrigin[STR_MAX] = {0};
    if (strlen(str) > 0) { return str; }
    char *realPath = realpath(SYS_SERIAL_PATH, NULL);
    if (realPath == NULL) { return NULL; }
    int fd = open(realPath, O_RDONLY);
    free(realPath);
    if (fd < 0) { return NULL; }
    ssize_t n = read(fd, strOrigin, sizeof(strOrigin) - 1);
    (void)close(fd);
    if (n > 0) {
        for (ssize_t j = 0; j < n && j < STR_MAX - 1; j++) { str[j] = strOrigin[j]; }
        str[(n < STR_MAX - 1) ? n : STR_MAX - 1] = '\0';
    }
    return str;
}
```

