/* UART 接收中断处理函数 */
static void UartIrqHandler(void)
{
    uint8_t rxBuf[512];              /* 收包缓冲 */
    uint32_t len = UartReadFifo(rxBuf, sizeof(rxBuf));
    if (len > 0) {
        if (LOS_SemPend(g_rxSem, 100) != LOS_OK) {   /* 等上次处理完 */
            printf("uart irq: drop frame, len=%u\n", len);
            return;
        }
        uint8_t *frame = (uint8_t *)LOS_MemAlloc(m_aucSysMem0, len);
        if (frame != NULL) {
            memcpy_s(frame, len, rxBuf, len);
            LOS_QueueWrite(g_rxQueue, frame, len, 0);
        }
        LOS_SemPost(g_rxSem);
    }
}
```

